const cleanData=data=>Object.fromEntries(Object.entries(data||{}).flatMap(([key,raw])=>{
  const value=humanValue(key,raw);
  if(value===null||value===undefined||value===''||(Array.isArray(value)&&value.length===0)||(typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).length===0)) return [];
  return [[key,value]];
}));
const cleanFiles=files=>(Array.isArray(files)?files:[]).map(file=>({
  nombre_original:file?.nombre_original||file?.name||file?.original_name||'Archivo adjunto',
  categoria:file?.categoria||file?.category||''
}));

const grupos=areas.map(area=>({
  area:area.nombre,
  servicios:selected.filter(service=>service?.area_id===area?.id).map(service=>{
    const draft=drafts[service?.tipo_servicio_slug]||{};
    return {servicio:service?.nombre,informacion:cleanData(draft.data),archivos:cleanFiles(draft.files)};
  })
})).filter(group=>group.servicios.length);

return {
  aviso_multiples_areas:grupos.length>1?'Se generará un número de pedido independiente para cada área seleccionada.':'',
  datos_generales:{nombre_apellido:pedido.nombre_apellido,telefono:pedido.telefono,correo:pedido.correo,area_solicitante:pedido.area_solicitante,tipos_pedido:areas.map(a=>a.nombre)},
  grupos
};
